// Claude devuelve, junto con la respuesta, un "usage": la factura de la consulta.
// Ahí miramos dos números:
//   cache_creation_input_tokens = tokens que se GUARDARON en el escritorio (caché)
//   cache_read_input_tokens     = tokens que se LEYERON del escritorio (10 veces más barato)
const consultas = $('2. Las consultas (parte variable)').all();

return $input.all().map((item, i) => {
  const respuesta = item.json;
  const factura = respuesta.usage || {};
  const guardados = factura.cache_creation_input_tokens || 0;
  const leidos = factura.cache_read_input_tokens || 0;

  // La respuesta es el JSON de la Guía 1 escrito como texto: lo abrimos.
  let datos = {};
  try {
    const texto = (respuesta.content || []).map(b => b.text || '').join('');
    datos = JSON.parse(texto.replace(/```json|```/g, '').trim());
  } catch (e) {
    datos = {};
  }

  let que_paso = 'No usó el caché: revisá que la parte fija no haya cambiado';
  if (guardados > 0) que_paso = 'Dejó el manual sobre el escritorio (esta vez cuesta un poco más)';
  if (leidos > 0) que_paso = 'Encontró el manual abierto: lo leyó 10 veces más barato';

  return { json: {
    consulta: consultas[i] ? consultas[i].json.quien : 'Consulta ' + (i + 1),
    que_paso,
    tokens_guardados_en_el_escritorio: guardados,
    tokens_leidos_del_escritorio: leidos,
    servicio: datos.servicio,
    prioridad: datos.prioridad
  } };
});
